    {
     "mota": "testua",
     "html": "Eman dezagun trukatutako partikularen masa <math display=\"inline\"><mi>m</mi></math> dela, bere abiadura <math display=\"inline\"><mrow><mi>c</mi><mi mathvariant=\"bold-italic\">𝜷</mi></mrow></math> eta Lorentzen faktorea <math display=\"inline\"><mi>γ</mi></math>. Ezkerreko partikularen masa <math display=\"inline\"><msub><mi>m</mi><mn>1</mn></msub></math> da, bere abiadura <math display=\"inline\"><mrow><mi>c</mi><msub><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn></msub></mrow></math> talka aurretik eta <math display=\"inline\"><mrow><mi>c</mi><msubsup><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn><mo>′</mo></msubsup></mrow></math> talka ondoren eta Lorentzen faktoreak <math display=\"inline\"><msub><mi>γ</mi><mn>1</mn></msub></math> eta <math display=\"inline\"><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup></math>. Honela idazten dira energiaren eta momentu linealaren kontserbazio-printzipioak partikularen xurgatze-prozesuan: <math display=\"block\"><mrow><mi>m</mi><mi>γ</mi><msup><mi>c</mi><mn>2</mn></msup><mo>+</mo><msub><mi>m</mi><mn>1</mn></msub><msub><mi>γ</mi><mn>1</mn></msub><msup><mi>c</mi><mn>2</mn></msup><mo>=</mo><msub><mi>m</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msup><mi>c</mi><mn>2</mn></msup><mo>,</mo></mrow></math> <math display=\"block\"><mrow><mi>m</mi><mi>γ</mi><mi>c</mi><mi mathvariant=\"bold-italic\">𝜷</mi><mo>+</mo><msub><mi>m</mi><mn>1</mn></msub><msub><mi>γ</mi><mn>1</mn></msub><mi>c</mi><msub><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn></msub><mo>=</mo><msub><mi>m</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mi>c</mi><msubsup><mi mathvariant=\"bold-italic\">𝜷</mi><mrow><mn>1</mn><mi>.</mi></mrow><mo>′</mo></msubsup></mrow></math> Hemendik, trukatutako partikularen ezaugarriak askatzen badira, <math display=\"block\"><mrow><mi>m</mi><mi>γ</mi><mo>=</mo><msub><mi>m</mi><mn>1</mn></msub><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>,</mo></mrow></math> <math display=\"block\"><mrow><mi>m</mi><mi>γ</mi><mi mathvariant=\"bold-italic\">𝜷</mi><mo>=</mo><msub><mi>m</mi><mn>1</mn></msub><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msubsup><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn><mo>′</mo></msubsup><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><msub><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>,</mo></mrow></math> erraz kalkulatzen da masaren karratua: <math display=\"block\"><mtable><mtr><mtd columnalign=\"right\" style=\"text-align: right; padding-right: 0\"><msup><mi>m</mi><mn>2</mn></msup></mtd><mtd columnalign=\"left\" style=\"text-align: left; padding-left: 0\"><mo>=</mo><msup><mi>m</mi><mn>2</mn></msup><msup><mi>γ</mi><mn>2</mn></msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>−</mo><msup><mi mathvariant=\"bold-italic\">𝜷</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mtd></mtr><mtr><mtd columnalign=\"right\" style=\"text-align: right; padding-right: 0\"></mtd><mtd columnalign=\"left\" style=\"text-align: left; padding-left: 0\"><mo>=</mo><msubsup><mi>m</mi><mn>1</mn><mn>2</mn></msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">[</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mn>2</mn></msup><mo>−</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msubsup><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn><mo>′</mo></msubsup><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><msub><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn></msub><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">]</mo></mrow></mtd></mtr><mtr><mtd columnalign=\"right\" style=\"text-align: right; padding-right: 0\"></mtd><mtd columnalign=\"left\" style=\"text-align: left; padding-left: 0\"><mo>=</mo><mn>2</mn><msubsup><mi>m</mi><mn>1</mn><mn>2</mn></msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>+</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msub><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn></msub><mo>⋅</mo><msubsup><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn><mo>′</mo></msubsup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mtd></mtr><mtr><mtd columnalign=\"right\" style=\"text-align: right; padding-right: 0\"></mtd><mtd columnalign=\"left\" style=\"text-align: left; padding-left: 0\"><mo>≤</mo><mn>2</mn><msubsup><mi>m</mi><mn>1</mn><mn>2</mn></msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>+</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo stretchy=\"false\" form=\"prefix\">|</mo><msub><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn></msub><mo stretchy=\"false\" form=\"prefix\">|</mo><mo stretchy=\"false\" form=\"prefix\">|</mo><msubsup><mi mathvariant=\"bold-italic\">𝜷</mi><mn>1</mn><mo>′</mo></msubsup><mo stretchy=\"false\" form=\"prefix\">|</mo><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mtd></mtr><mtr><mtd columnalign=\"right\" style=\"text-align: right; padding-right: 0\"></mtd><mtd columnalign=\"left\" style=\"text-align: left; padding-left: 0\"><mo>=</mo><mn>2</mn><msubsup><mi>m</mi><mn>1</mn><mn>2</mn></msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>+</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msqrt><mrow><mn>1</mn><mo>−</mo><msubsup><mi>γ</mi><mn>1</mn><mrow><mi>−</mi><mn>2</mn></mrow></msubsup></mrow></msqrt><msqrt><mrow><mn>1</mn><mo>−</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msup><mi></mi><mrow><mi>−</mi><mn>2</mn></mrow></msup></mrow></msqrt><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mtd></mtr><mtr><mtd columnalign=\"right\" style=\"text-align: right; padding-right: 0\"></mtd><mtd columnalign=\"left\" style=\"text-align: left; padding-left: 0\"><mo>=</mo><mn>2</mn><msubsup><mi>m</mi><mn>1</mn><mn>2</mn></msubsup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>−</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>+</mo><msqrt><mrow><msubsup><mi>γ</mi><mn>1</mn><mn>2</mn></msubsup><mo>−</mo><mn>1</mn></mrow></msqrt><msqrt><mrow><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msup><mi></mi><mn>2</mn></msup><mo>−</mo><mn>1</mn></mrow></msqrt><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>&lt;</mo><mn>0</mn><mi>.</mi></mtd></mtr></mtable></math> Azken desberdintza frogatzeko, <math display=\"block\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msubsup><mi>γ</mi><mn>1</mn><mn>2</mn></msubsup><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msup><mi></mi><mn>2</mn></msup><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>&lt;</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mn>2</mn></msup></mrow></math> egiaztatu behar da; baina hau <math display=\"block\"><mrow><mi>−</mi><msubsup><mi>γ</mi><mn>1</mn><mn>2</mn></msubsup><mo>−</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><msup><mi></mi><mn>2</mn></msup><mo>&lt;</mo><mi>−</mi><mn>2</mn><msub><mi>γ</mi><mn>1</mn></msub><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup></mrow></math> moduan idazten da eta partikularen abiadura aldatu delako betetzen den ondoko emaitzaren ondorioa da: <math display=\"block\"><mrow><msup><mrow><mi>−</mi><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msub><mi>γ</mi><mn>1</mn></msub><mo>−</mo><msubsup><mi>γ</mi><mn>1</mn><mo>′</mo></msubsup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow><mn>2</mn></msup><mo>&lt;</mo><mn>0</mn><mi>.</mi></mrow></math>"
    }
